import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    N = int(input_data[0])

    # An alkane must have at least 1 carbon and 4 hydrogens (5 vertices).
    if N < 5:
        print(-1)
        return

    deg = [0] * (N + 1)

    edges_u = [0] * (N - 1)
    edges_v = [0] * (N - 1)
    idx = 1
    for i in range(N - 1):
        u = int(input_data[idx])
        v = int(input_data[idx+1])
        idx += 2
        deg[u] += 1
        deg[v] += 1
        edges_u[i] = u
        edges_v[i] = v

    good = [d >= 4 for d in deg]

    has_good = False
    for i in range(1, N + 1):
        if good[i]:
            has_good = True
            break

    if not has_good:
        print(-1)
        return

    adj = [[] for _ in range(N + 1)]
    for i in range(N - 1):
        u = edges_u[i]
        v = edges_v[i]
        if good[u] and good[v]:
            adj[u].append(v)
            adj[v].append(u)

    visited = [False] * (N + 1)
    parent = [0] * (N + 1)

    # f[u]: max carbons in u's subtree if u uses 1 edge to connect to its parent (so it can pick up to 3 children)
    # g[u]: max carbons in u's subtree if u is the root of the carbon tree (so it can pick up to 4 children)
    f = [0] * (N + 1)
    g = [0] * (N + 1)

    max_carbons = 0

    for i in range(1, N + 1):
        if good[i] and not visited[i]:
            order = []
            stack = [i]
            visited[i] = True
            parent[i] = 0

            # Iterative DFS to build post-order evaluation string
            while stack:
                u = stack.pop()
                order.append(u)
                for v in adj[u]:
                    if not visited[v]:
                        visited[v] = True
                        parent[v] = u
                        stack.append(v)

            # Iterate in post-order (bottom-up DP)
            for j in range(len(order) - 1, -1, -1):
                u = order[j]
                vals = []
                for v in adj[u]:
                    if v != parent[u]:
                        vals.append(f[v])

                # We greedily take the children subtrees that offer the most carbons
                vals.sort(reverse=True)

                f[u] = 1 + sum(vals[:3])
                g[u] = 1 + sum(vals[:4])

                if g[u] > max_carbons:
                    max_carbons = g[u]

    if max_carbons == 0:
        print(-1)
    else:
        # A valid alkane tree of C carbons ALWAYS contains exactly 3*C + 2 vertices.
        print(3 * max_carbons + 2)

if __name__ == '__main__':
    solve()
